INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT159-S3-Q11$batch04$, 159, 3, 11, $batch04$Paradox$batch04$, $batch04$The crocodiles of Lake Victoria, in East Africa, sometimes attack humans that venture into their habitat. The number of attacks on people by these crocodiles has increased significantly in the last 20 years. This is despite the fact that the number of crocodiles in the lake has not increased in that time and the crocodiles have no less food available.$batch04$, $batch04$Which one of the following, if true, most helps to explain the increase in the incidence of crocodile attacks on humans?$batch04$, $batch04$E$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Wildlife authorities on Lake Victoria sometimes destroy crocodiles that they believe to be responsible for attacks on humans.$batch04$, $batch04$Deepens Paradox$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$About 100 crocodiles inhabit the part of Lake Victoria where most of the attacks on humans have occurred.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$More attacks on humans by crocodiles occur in Lake Victoria than in any other part of Africa.$batch04$, $batch04$Irrelevant Comparison$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Adult crocodiles in Lake Victoria are generally unafraid of humans or their boats.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$People now fish in more parts of Lake Victoria than they did in previous decades.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$In the last 20 years, the number of crocodiles in the lake has not risen, and they have no less food.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Crocodile attacks on humans have risen significantly?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The crocodiles have not changed, so look at the humans. If people are going into crocodile territory more often, there would be more chances for an attack.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a change in how much people come into contact with the crocodiles.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Killing crocodiles that attack should reduce attacks, not increase them.$batch04$), ($batch04$B$batch04$, $batch04$A count of crocodiles in one area does not show any change over 20 years.$batch04$), ($batch04$C$batch04$, $batch04$Comparing Lake Victoria with the rest of Africa does not explain the increase over time.$batch04$), ($batch04$D$batch04$, $batch04$Crocodiles being unafraid of humans is not shown to be new, so it does not explain why attacks went up.$batch04$), ($batch04$E$batch04$, $batch04$People now fish in more parts of the lake, so they meet crocodiles more often. More contact means more attacks, with the same number of crocodiles.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT159-S3-Q11$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
